/**
 * Hook for managing droid-docs script data
 * 管理从 droid-docs API 获取的脚本数据
 */

'use client'

import { useState, useCallback, useEffect } from 'react';
import {
  fetchExamplesMap,
  fetchScript,
  IScript,
  DifficultyLevel,
  IExamplesAllLevelMap
} from '@src/services/droid-docs-api';

export interface UseDroidDocsScriptsResult {
  // 脚本数据
  examplesMap: IExamplesAllLevelMap | null;
  selectedLevel: DifficultyLevel;
  selectedScript: IScript | null;
  scriptContent: string;

  // 状态标志
  isLoadingMap: boolean;
  isLoadingScript: boolean;
  mapError: Error | null;
  scriptError: Error | null;

  // 操作方法
  setSelectedLevel: (level: DifficultyLevel) => void;
  selectScript: (script: IScript) => Promise<void>;
  updateScriptContent: (content: string) => void;
  refreshScriptContent: () => Promise<void>;
}

/**
 * Hook: 使用 droid-docs API 获取脚本数据
 * @param lang 语言代码，默认为 'zh-CN'
 * @returns 脚本数据和操作方法
 */
export function useDroidDocsScripts(lang: string = 'zh-CN'): UseDroidDocsScriptsResult {
  // 脚本地图状态
  const [examplesMap, setExamplesMap] = useState<IExamplesAllLevelMap | null>(null);
  console.log('[useDroidDocsScripts] 初始化 examplesMap');

  // 难度级别选择状态
  const [selectedLevel, setSelectedLevelState] = useState<DifficultyLevel>('beginner');
  console.log('[useDroidDocsScripts] 初始化 selectedLevel: beginner');

  // 脚本选择状态
  const [selectedScript, setSelectedScript] = useState<IScript | null>(null);
  console.log('[useDroidDocsScripts] 初始化 selectedScript: null');

  // 脚本内容状态
  const [scriptContent, setScriptContent] = useState('');
  console.log('[useDroidDocsScripts] 初始化 scriptContent: 空字符串');

  // 加载状态
  const [isLoadingMap, setIsLoadingMap] = useState(false);
  console.log('[useDroidDocsScripts] 初始化 isLoadingMap: false');

  const [isLoadingScript, setIsLoadingScript] = useState(false);
  console.log('[useDroidDocsScripts] 初始化 isLoadingScript: false');

  // 错误状态
  const [mapError, setMapError] = useState<Error | null>(null);
  console.log('[useDroidDocsScripts] 初始化 mapError: null');

  const [scriptError, setScriptError] = useState<Error | null>(null);
  console.log('[useDroidDocsScripts] 初始化 scriptError: null');

  // 加载脚本地图（仅在初始化时执行）
  useEffect(() => {
    const loadMap = async () => {
      console.log('[useDroidDocsScripts] 开始加载脚本地图');
      setIsLoadingMap(true);
      setMapError(null);

      try {
        const map = await fetchExamplesMap(lang, false);
        console.log('[useDroidDocsScripts] 脚本地图加载成功');
        setExamplesMap(map);

        // 自动选择初级的第一个脚本
        if (map.beginner && map.beginner.length > 0) {
          console.log('[useDroidDocsScripts] 自动选择初级的第一个脚本:', map.beginner[0].name);
          setSelectedScript(map.beginner[0]);
          setScriptContent(map.beginner[0].script);
        }
      } catch (error: any) {
        console.error('[useDroidDocsScripts] 脚本地图加载失败:', error.message);
        setMapError(error);
      } finally {
        setIsLoadingMap(false);
      }
    };

    loadMap();
  }, [lang]);

  // 设置难度级别
  const setSelectedLevel = useCallback((level: DifficultyLevel) => {
    console.log('[useDroidDocsScripts] 设置难度级别:', level);
    setSelectedLevelState(level);

    // 重置脚本选择
    if (examplesMap && examplesMap[level] && examplesMap[level].length > 0) {
      console.log('[useDroidDocsScripts] 自动选择新级别的第一个脚本:', examplesMap[level][0].name);
      setSelectedScript(examplesMap[level][0]);
      setScriptContent(examplesMap[level][0].script);
    } else {
      console.log('[useDroidDocsScripts] 新级别没有脚本');
      setSelectedScript(null);
      setScriptContent('');
    }
  }, [examplesMap]);

  // 选择脚本并加载内容
  const selectScript = useCallback(async (script: IScript) => {
    console.log('[useDroidDocsScripts] 选择脚本:', script.name);
    setSelectedScript(script);
    setIsLoadingScript(true);
    setScriptError(null);

    try {
      // 从 path 中提取 category 和 name
      // path 格式: "beginner/vibrate"
      const [category, name] = script.path.split('/');
      console.log('[useDroidDocsScripts] 从 path 提取 category:', category, 'name:', name);

      if (!category || !name) {
        throw new Error(`Invalid script path: ${script.path}`);
      }

      const fullScript = await fetchScript(
        category as DifficultyLevel,
        name,
        lang,
        true  // 获取完整内容
      );

      console.log('[useDroidDocsScripts] 脚本内容加载成功');
      setScriptContent(fullScript.script);
    } catch (error: any) {
      console.error('[useDroidDocsScripts] 脚本内容加载失败:', error.message);
      setScriptError(error);
    } finally {
      setIsLoadingScript(false);
    }
  }, [lang]);

  // 更新脚本内容
  const updateScriptContent = useCallback((content: string) => {
    console.log('[useDroidDocsScripts] 更新脚本内容，新长度:', content.length);
    setScriptContent(content);
  }, []);

  // 刷新脚本内容（重新从服务器加载）
  const refreshScriptContent = useCallback(async () => {
    if (!selectedScript) {
      console.log('[useDroidDocsScripts] 没有选择脚本，无法刷新');
      return;
    }

    console.log('[useDroidDocsScripts] 刷新脚本内容:', selectedScript.name);
    await selectScript(selectedScript);
  }, [selectedScript, selectScript]);

  return {
    examplesMap,
    selectedLevel,
    selectedScript,
    scriptContent,
    isLoadingMap,
    isLoadingScript,
    mapError,
    scriptError,
    setSelectedLevel,
    selectScript,
    updateScriptContent,
    refreshScriptContent
  };
}
