/**
 * Droid Docs API Service
 * 用于与 droid-docs 项目的 API 交互
 */

export interface IScript {
  name: string;
  desc: string;
  path: string;
  version: number;
  script: string;
}

export type DifficultyLevel = 'beginner' | 'intermediate' | 'advanced';

export interface IExamplesMap {
  [key: string]: IScript;
}

export interface IExamplesAllLevelMap {
  beginner: IScript[];
  intermediate: IScript[];
  advanced: IScript[];
}

export interface ExamplesMapResponse {
  lang: string;
  script: boolean;
  total: number;
  count: {
    beginner: number;
    intermediate: number;
    advanced: number;
  };
  data: IExamplesAllLevelMap;
}

// API 基础 URL - 从环境变量或默认值读取
const getApiBaseUrl = (): string => {
  console.log('[DroidDocsApi] 获取 API 基础 URL');

  // 在浏览器环境中，使用 localhost
  if (typeof window !== 'undefined') {
    const baseUrl = 'https://droid-docs.vm-ubuntu.droidlego.com';
    console.log('[DroidDocsApi] 浏览器环境，使用 baseUrl:', baseUrl);
    return baseUrl;
  }

  // 服务端环境
  const baseUrl = 'https://droid-docs.vm-ubuntu.droidlego.com';
  console.log('[DroidDocsApi] 服务端环境，使用 baseUrl:', baseUrl);
  return baseUrl;
};

/**
 * 获取完整的脚本地图（按难度级别组织）
 * @param lang 语言代码，默认为 'zh-CN'
 * @param withScript 是否包含脚本内容，默认为 false
 * @returns 包含所有脚本的地图
 */
export async function fetchExamplesMap(
  lang: string = 'zh-CN',
  withScript: boolean = false
): Promise<IExamplesAllLevelMap> {
  console.log('[DroidDocsApi] 开始获取脚本地图', { lang, withScript });

  try {
    const apiUrl = `${getApiBaseUrl()}/api/examples-map`;
    const params = new URLSearchParams({
      lang,
      script: String(withScript)
    });

    const fullUrl = `${apiUrl}?${params.toString()}`;
    console.log('[DroidDocsApi] 请求 URL:', fullUrl);

    const response = await fetch(fullUrl, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    console.log('[DroidDocsApi] 响应状态码:', response.status);

    if (!response.ok) {
      console.error('[DroidDocsApi] 响应状态不为 200, 状态码:', response.status);
      throw new Error(`Failed to fetch examples map: ${response.status} ${response.statusText}`);
    }

    const data = await response.json() as ExamplesMapResponse;
    console.log('[DroidDocsApi] 获取脚本地图成功', { total: data.total, count: data.count });

    return data.data;
  } catch (error: any) {
    console.error('[DroidDocsApi] 获取脚本地图失败:', error.message);
    throw error;
  }
}

/**
 * 获取单个脚本的完整内容
 * @param category 脚本分类（beginner/intermediate/advanced）
 * @param name 脚本名称
 * @param lang 语言代码，默认为 'zh-CN'
 * @param withScript 是否包含脚本内容，默认为 true
 * @returns 脚本对象
 */
export async function fetchScript(
  category: DifficultyLevel,
  name: string,
  lang: string = 'zh-CN',
  withScript: boolean = true
): Promise<IScript> {
  console.log('[DroidDocsApi] 开始获取单个脚本', { category, name, lang, withScript });

  try {
    const apiUrl = `${getApiBaseUrl()}/api/script`;
    const params = new URLSearchParams({
      category,
      name,
      lang,
      script: String(withScript)
    });

    const fullUrl = `${apiUrl}?${params.toString()}`;
    console.log('[DroidDocsApi] 请求 URL:', fullUrl);

    const response = await fetch(fullUrl, {
      method: 'GET',
      headers: {
        'Content-Type': 'application/json'
      }
    });

    console.log('[DroidDocsApi] 响应状态码:', response.status);

    if (!response.ok) {
      console.error('[DroidDocsApi] 响应状态不为 200, 状态码:', response.status);
      throw new Error(`Failed to fetch script: ${response.status} ${response.statusText}`);
    }

    const script = await response.json() as IScript;
    console.log('[DroidDocsApi] 获取脚本成功:', script.name);

    return script;
  } catch (error: any) {
    console.error('[DroidDocsApi] 获取脚本失败:', error.message);
    throw error;
  }
}
